pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if fitting_bins_count == 1 {
        // This bin is the last chance before opening a new bin
        if post_residual >= next_item_size {
            // Favor filling this bin since it's our last chance
            score -= 0.5;
        } else {
            // Penalize not being able to fit the next item in this bin
            score += 1.5;
        }
    }

    if post_residual < mean_residual {
        // Penalize creating a bin with less remaining space than average
        score += 0.3 * (mean_residual - post_residual) as f64;
    } else if post_residual > mean_residual + 20 {
        // Reward having significantly more space than average
        score -= 0.2 * (post_residual - (mean_residual + 20)) as f64;
    }

    score
}

