    let mut score = 0.0;

    // Penalize creating bins with very low capacity usage
    if bin_capacity - post_residual < 15 {
        score += (bin_capacity - post_residual) as f64 * 3.0;
    }

    // Reward bins that have a higher likelihood of fitting the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size - post_residual) as f64 * 2.5;
    }

    // Penalize bins with very high residual space, as it indicates inefficiency
    if post_residual > bin_capacity / 3 {
        score += (post_residual - bin_capacity / 3) as f64 * 1.5;
    }

    // Reward bins that are close to being full but can fit the next item
    if fitting_bins_count == 1 && post_residual >= next_item_size {
        score -= (next_item_size - post_residual) as f64 * 3.0;
    }

    // Penalize creating too many open bins
    score += (open_bins_count as f64 / total_items as f64).powi(2) * 1.5;

    // Reward bins with a better-than-average residual space
    if post_residual > mean_residual {
        score -= (post_residual - mean_residual) as f64 * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = -post_residual as f64;
    score += (bin_capacity - bin_residual) as f64 * 0.1; // Penalize bins with less capacity left
    if open_bins_count > 1 {
        score -= (open_bins_count - 1) as f64 * 0.3; // Penalize having more than one open bin
    }
    if post_residual < 10 {
        score -= (10 - post_residual) as f64 * 2.5; // Penalize bins with small post-residuals
    }
    score += (fitting_bins_count as f64 / open_bins_count as f64).ln().max(1.0); // Reward bins that fit more items
    if bin_residual < item_size {
        score -= (bin_capacity - bin_residual) as f64 * 0.5; // Penalize bins with insufficient residual space for current item
    }
    let score = score * 0.7 + ((score * 0.7 + post_residual as f64 * 0.3) * 0.3); // Combine scores with a weighted average
    score
}

